const{Vec3}=require('vec3');bot.clearControlStates();bot.pathfinder.setGoal(null);let c,receipts=[];try{c=await bot.openChest(bot.blockAt(new Vec3(7,67,82)));for(const name of['gravel','spruce_planks']){const it=bot.inventory.items().find(i=>i.name===name);if(!it)continue;const n=it.count,b=c.containerItems().filter(i=>i.name===name).reduce((s,i)=>s+i.count,0);await c.deposit(it.type,null,n);await bot.waitForTicks(5);const a=c.containerItems().filter(i=>i.name===name).reduce((s,i)=>s+i.count,0);receipts.push([name,n,b,a,a-b===n]);}}finally{if(c)c.close()}return{receipts,p:bot.entity.position,hp:bot.health,foundation:[[6,66,84],[7,66,84],[7,65,83],[6,65,83],[6,65,82],[7,65,82],[5,66,83]].map(a=>[a,bot.blockAt(new Vec3(...a))?.name]),cobble:bot.findBlocks({matching:b=>b.name==='cobblestone',maxDistance:5,count:80}).map(p=>[p.x,p.y,p.z]),walls:[[6,67,84],[7,67,84],[6,68,84],[7,68,84]].map(a=>[a,bot.blockAt(new Vec3(...a))?.name])};
